reference_solution:
def count_symmetric_integers(low,high):
    answer=0
    for value in range(low,high+1):
        digits=str(value);half=len(digits)//2
        if len(digits)%2==0 and sum(map(int,digits[:half]))==sum(map(int,digits[half:])):answer+=1
    return answer

